export * from 'window-function'
export type WindowName = Exclude<keyof typeof import('window-function'), 'generate' | 'apply' | 'enbw' | 'scallopLoss' | 'cola'>
/** Fill a window; periodic defaults to true. */
export default function window(name: WindowName, length: number, options?: { periodic?: boolean }): Float64Array
/** Multiply in place by a repeating window, returning the same array. */
export function apply<T extends Float32Array | Float64Array | number[]>(data: T, win: ArrayLike<number>): T
export function cola(win: ArrayLike<number>, hop: number, options?: { squared?: boolean; tolerance?: number }): {
  ok: boolean; ripple: number; mean: number
}
